  'page.a11y.report_p': 'Pokud jste narazili na obsah nebo funkci, kterou nelze dobře použít se čtečkou obrazovky, klávesnicí nebo s jiným asistivním nástrojem, napište nám. Pokusíme se to napravit a v mezidobí poskytneme obsah v jiné, dostupné formě.',
