  // STRÁNKA: Podpoř účastníky
  'page.support.title': 'Podpoř účastníky',
  'page.support.meta_title': 'Podpoř účastníky — Pán Prstenů 2026',
  'page.support.description': 'Pomoz někomu dostat se do Středozemě. Pokud máš možnost a chuť, můžeš přispět na registrační poplatek pro účastníka, kterého by jinak akce minula.',
  'page.support.subtitle': 'Pomoz někomu dostat se do Středozemě.',
  'page.support.intro_p1': 'Někteří účastníci se na akci chtějí dostat, ale registrační poplatek pro ně může být překážkou. Pokud máš možnost a chuť někoho podpořit, můžeš přispět na registrační poplatek jinému hráči.',
  'page.support.intro_p2_pre': 'Podpora může být ',
  'page.support.intro_p2_strong1': 'konkrétní',
  'page.support.intro_p2_mid': ', pokud víš, komu chceš pomoct, nebo ',
  'page.support.intro_p2_strong2': 'obecná',
  'page.support.intro_p2_post': ' — tehdy ji použijeme pro účastníky, kteří se nám ozvou s prosbou o pomoc.',
  'page.support.intro_p3': 'Vždy se snažíme postupovat citlivě. Nezveřejňujeme osobní situaci účastníků a domluvu řešíme individuálně.',
  'page.support.h_options': 'Varianty podpory',
  'page.support.opt_specific_title': 'Konkrétního účastníka',
  'page.support.opt_specific_desc': 'Vím, komu chci pomoct. Mám konkrétního přítele, mladšího účastníka, někoho ze své skupiny nebo komunity.',
  'page.support.opt_general_title': 'Obecnou podporu',
  'page.support.opt_general_desc': 'Chci přispět na účast někoho, kdo by jinak nemohl jet. Vyberte sami, komu pomoc dorazí.',
  'page.support.opt_other_title': 'Pomoct jinak než finančně',
  'page.support.opt_other_desc': 'Mohu nabídnout svezení autem, sdílení vybavení, kostýmu, stanu, zázemí, mentoring pro nováčka — nebo jinou formu, která dává smysl. Domluvíme se podle situace.',
  'page.support.h_how': 'Jak to funguje',
  'page.support.how_1_pre': 'Napiš nám na ',
  'page.support.how_1_post': ' s předmětem „Podporám účastníka".',
  'page.support.how_2': 'Napiš, jestli chceš podpořit konkrétního účastníka, obecně, nebo nabídnout pomoc jinou než finanční.',
  'page.support.how_3': 'Domluvíme se na konkrétní částce, formě a způsobu předání.',
  'page.support.how_4': 'Po předání ti potvrdíme, že podpora dorazila k účastníkovi (s respektem k jeho soukromí).',
  'page.support.alert': 'S podporou pracujeme jako se závazkem. Pokud nás kontaktuješ, ozveme se ti zpět co nejrychleji a domluvíme detaily. Nikoho nezavazujeme zveřejněním ani veřejným poděkováním, pokud o to nestojíš.',
  'page.support.h_related': 'Související',
  'page.support.rel_1_label': 'Když je registrační poplatek problém',
  'page.support.rel_1_post': ' — pohled z druhé strany.',
  'page.support.rel_2_label': 'Registrace a registrační poplatek',
  'page.support.rel_2_post': ' — přehled cen.',
  'page.support.rel_3_label': 'Pořadatel',
  'page.support.rel_3_post': ' — Moravian LARP, z. s. a kontaktní údaje.',
  'page.support.rel_4_label': 'Kontakt',
  'page.support.rel_4_post': ' — když chceš pomoct nebo se zeptat.',
  'page.support.cta_heading': 'Chceš podpořit účastníky?',
  'page.support.cta_body': 'Napiš nám. I drobnější příspěvek může pro někoho znamenat, že jet může. Středozem si pamatuje ty, kteří přiložili polínko do ohně.',
  'page.support.btn_support': 'Chci podpořit účastníky',
  'page.support.btn_registration': 'Registrace',

  // STRÁNKA: Fotky a video
  'page.photos.title': 'Fotky a video',
  'page.photos.description': 'Co se děje s fotografiemi a videem z akce, jak fungují souhlasy a jak požádat o omezení zveřejnění podobizny.',
  'page.photos.subtitle': 'Co se z akce fotografuje, jak se to používá, a jak požádat o omezení.',
  'page.photos.intro_pre': 'Na akci pracují domluvení fotografové a kameramani. Pořizují záznamy pro ',
  'page.photos.intro_strong': 'dokumentaci akce, propagaci dalších ročníků, sociální sítě spolku a komunitní fotogalerii',
  'page.photos.intro_post': '. Vedle nich fotí i samotní účastníci.',
  'page.photos.h_layers': 'Tři vrstvy použití',
  'page.photos.layer_official_title': 'Oficiální dokumentace',
  'page.photos.layer_official_desc': 'Fotky a video pořizované organizátorem nebo pověřenými fotografy. Slouží pro web, sociální sítě a propagaci ročníku.',
  'page.photos.layer_private_title': 'Soukromé focení',
  'page.photos.layer_private_desc': 'Účastníci si fotí pro vlastní vzpomínky a komunitní sdílení. Bez komerčního využití.',
  'page.photos.layer_commercial_title': 'Komerční / mediální',
  'page.photos.layer_commercial_desc': 'Pro novináře, mediální použití, obchodní účely. Vyžaduje předchozí domluvu s organizátory a vlastní souhlasy zachycených.',
  'page.photos.h_consent': 'Souhlas účastníka',
  'page.photos.consent_p1_pre': 'Při registraci na akci souhlasíte s pořizováním fotografií a videozáznamů pro ',
  'page.photos.consent_p1_strong': 'dokumentaci a propagaci akce',
  'page.photos.consent_p1_post': ' ze strany organizátora. Tento souhlas nezahrnuje druhotné komerční využití třetími stranami.',
  'page.photos.consent_p2_pre': 'Pokud máš vážný důvod, proč nechceš být na propagačních fotografiích rozpoznatelný/á (např. profesionální kontext, ochrana soukromí), ',
  'page.photos.consent_p2_strong': 'kontaktuj nás předem',
  'page.photos.consent_p2_post': ' nebo nahlas to přímo při registraci na místě.',
  'page.photos.h_minors': 'Pro rodiče a nezletilé účastníky',
  'page.photos.minors_l1_pre': 'Souhlas s fotografováním je součástí ',
  'page.photos.minors_l1_strong': 'Přihlášky pro hráče pod 18 let',
  'page.photos.minors_l1_post': ', kterou podepisuje zákonný zástupce.',
  'page.photos.minors_l2_pre': 'Pokud zákonný zástupce nesouhlasí s pořizováním nebo zveřejňováním podobizny dítěte, je nutné to ',
  'page.photos.minors_l2_strong': 'uvést písemně',
  'page.photos.minors_l2_post': ' v přihlášce nebo sdělit při registraci.',
  'page.photos.minors_l3': 'U dětí kladneme zvýšený důraz na ohleduplnost — necitlivé situace nefotíme ani nesdílíme.',
  'page.photos.h_rules': 'Pravidla pro fotografy a kameramany',
  'page.photos.rules_intro_pre': 'Jste fotograf nebo kameraman, který přijíždí akci dokumentovat? Plný přehled pravidel najdete v sekci ',
  'page.photos.rules_intro_link': 'Foto, video a média',
