  'page.stalls.you_l1': 'vlastní stánek a vybavení,',
  'page.stalls.you_l2': 'prodejní sortiment,',
  'page.stalls.you_l3': 'obsluhu,',
  'page.stalls.you_l4': 'případnou pokladnu / platby,',
  'page.stalls.you_l5': 'odpovědnost za zboží,',
  'page.stalls.you_l6': 'registraci na akci (hrající / nehrající).',
  'page.stalls.h_expect': 'Co od stánkařů čekáme',
  'page.stalls.exp_l1': 'Včasnou domluvu před akcí.',
  'page.stalls.exp_l2': 'Popis sortimentu nebo služby.',
  'page.stalls.exp_l3': 'Informaci o požadavcích na prostor, auto, elektřinu, vodu a zázemí.',
  'page.stalls.exp_l4': 'Vlastní vybavení stánku.',
  'page.stalls.exp_l5': 'Čistotu a úklid svého prostoru.',
  'page.stalls.exp_l6': 'Dodržování pokynů organizátorů.',
