  'page.testimonials.q2_text': 'When my daughter saw the elves give her a flower crown by the evening fire, I knew we were coming back.',
  'page.testimonials.q2_author': 'Petr · companion · parent',
  'page.testimonials.q3_text': 'Friday in the camp had an atmosphere I can’t describe. Coins, the pub, bargaining — that was exactly it.',
