  'page.photos.title': 'Photos and video',
  'page.photos.description': 'What happens with photos and video from the event, how consents work and how to ask for restriction of likeness publication.',
  'page.photos.subtitle': 'What is photographed at the event, how it is used, and how to ask for restrictions.',
  'page.photos.intro_pre': 'There are agreed photographers and videographers at the event. They take footage for ',
  'page.photos.intro_strong': 'event documentation, promotion of future editions, the association’s social media and the community photo gallery',
  'page.photos.intro_post': '. Participants also take their own photos.',
  'page.photos.h_layers': 'Three layers of use',
  'page.photos.layer_official_title': 'Official documentation',
  'page.photos.layer_official_desc': 'Photos and video taken by the organiser or appointed photographers. Used for the website, social media and edition promotion.',
  'page.photos.layer_private_title': 'Private photography',
  'page.photos.layer_private_desc': 'Participants take photos for their own memories and community sharing. No commercial use.',
  'page.photos.layer_commercial_title': 'Commercial / media',
  'page.photos.layer_commercial_desc': 'For journalists, media use, business purposes. Requires prior agreement with the organisers and the photographers’ own consents from the people captured.',
  'page.photos.h_consent': 'Participant consent',
  'page.photos.consent_p1_pre': 'By registering for the event you consent to the taking of photos and video for the ',
  'page.photos.consent_p1_strong': 'documentation and promotion of the event',
  'page.photos.consent_p1_post': ' by the organiser. This consent does not include secondary commercial use by third parties.',
  'page.photos.consent_p2_pre': 'If you have a serious reason for not wanting to be recognisable in promotional photos (e.g. professional context, privacy), ',
  'page.photos.consent_p2_strong': 'contact us in advance',
  'page.photos.consent_p2_post': ' or report it directly at on-site registration.',
  'page.photos.h_minors': 'For parents and minor participants',
  'page.photos.minors_l1_pre': 'The photo consent is part of the ',
  'page.photos.minors_l1_strong': 'Application for players under 18',
  'page.photos.minors_l1_post': ', signed by the legal guardian.',
  'page.photos.minors_l2_pre': 'If the legal guardian does not consent to taking or publishing the child’s likeness, it must be ',
  'page.photos.minors_l2_strong': 'stated in writing',
  'page.photos.minors_l2_post': ' in the application or communicated at registration.',
  'page.photos.minors_l3': 'For children we place extra emphasis on consideration — we don’t photograph or share insensitive situations.',
  'page.photos.h_rules': 'Rules for photographers and videographers',
  'page.photos.rules_intro_pre': 'Are you a photographer or videographer coming to document the event? The full rules overview is in the section ',
  'page.photos.rules_intro_link': 'Photo, video and media',
  'page.photos.rules_intro_post': '. Briefly:',
  'page.photos.rules_l1': 'The game and players always take priority — you don’t obstruct or disturb.',
  'page.photos.rules_l2': 'The costume requirement also applies to photographers and videographers.',
  'page.photos.rules_l3': 'Drones only by prior agreement with the organisers.',
  'page.photos.rules_l4': 'Commercial use of taken photos requires your own consents from the people captured.',
  'page.photos.h_request': 'Request to restrict publication',
  'page.photos.request_p': 'If you see your photo on our website or social media and don’t want it to remain there, write us:',
  'page.photos.request_email_label': 'E-mail',
  'page.photos.request_subject_label': 'Subject',
  'page.photos.request_subject_value': '"Photos and video — restriction request"',
  'page.photos.request_response': 'Include the URL or attach the specific photo. We reply within 30 days at the latest and will remove or replace the photo where possible.',
  'page.photos.related_title': 'Related',
  'page.photos.related_l1': 'GDPR / Privacy',
  'page.photos.related_l2': 'Accessibility statement',
  'page.photos.related_l3': 'Rules for photographers and videographers',
  'page.photos.related_l4': 'For media and journalists',

  'page.vendors.title': 'Vendors and stalls',
  'page.vendors.description': 'Themed stalls and vendors at Battle for Middle-earth 2026 — costumes, fabrics, leather accessories, jewellery, weapons and other Middle-earth gear.',
  'page.vendors.subtitle': 'Market, crafts and things that belong in Middle-earth.',
  'page.vendors.intro': 'On site you’ll find themed gear — costumes, fabrics, leather accessories, jewellery, weapons and other things that may come in handy in Middle-earth.',
  'page.vendors.warning': 'The organisers do not guarantee that everything from everyone will be available on site. If you need something specific from a specific vendor, arrange it with them in advance.',
  'page.vendors.empty_title': 'Vendor list in preparation',
  'page.vendors.empty_body': 'We accept vendor applications continuously. Once we confirm the first stalls, they will appear here with assortment descriptions and links.',
  'page.vendors.empty_btn': 'I want to apply as a vendor',
  'page.vendors.highlights_label': 'What will be on site',
  'page.vendors.cta_heading': 'Are you a vendor and want to join?',
  'page.vendors.cta_body': 'Find all the details on the vendors page — what we’re looking for, how to apply, what we provide and what the vendor provides.',
  'page.vendors.cta_btn': 'For vendors',

