  'page.media.desc_strong1': 'The Lord of the Rings — Battle for Middle-earth',
  'page.media.desc_mid': ' is a large fantasy larp battle inspired by the world of J. R. R. Tolkien. Participants in costume represent armies and peoples of Middle-earth and take part in a weekend-long game with emphasis on atmosphere, safety, fair play and community experience. The event is organised by ',
  'page.media.desc_strong2': 'Moravian LARP, z. s.',
