  'page.safety.meta_title': 'Safety and crisis situations',
  'page.safety.description': 'A practical overview of what to do in case of injury, lost child, fire, storm or conflict at the event. Printable version for the camp.',
  'page.safety.bc_label': 'Safety',
  'page.safety.title': 'Safety and crisis situations',
  'page.safety.subtitle': 'What to do when something happens. A short practical card — print it out, take it with you.',
  'page.safety.card_title': 'Quick safety card',
  'page.safety.emergency_label': 'Emergency line',
  'page.safety.ems_label': 'Ambulance',
  'page.safety.fire_label': 'Fire brigade',
  'page.safety.police_label': 'Police',
  'page.safety.location_label': 'Location for emergency services',
  'page.safety.location_value': 'Křtiny / Bukovina, southern Moravia',
  'page.safety.gps_label': 'GPS',
  'page.safety.main_org_label': 'Main organiser',
  'page.safety.main_org_name': 'Mealtiner',
  'page.safety.email_label': 'E-mail',
  'page.safety.medic_label': 'Medic on site',
  'page.safety.medic_value': 'At registration / org tent (qualified medic for the whole event)',
  'page.safety.print_tip': 'Tip: print this card (Ctrl/Cmd+P) and take it with you. The signal in the area is not always reliable.',
  'page.safety.h_procedures': 'Procedures in crisis situations',
  'page.safety.p1_title': 'When someone is injured',
  'page.safety.p1_s1': 'Stop the dangerous activity.',
  'page.safety.p1_s2': 'Secure the surroundings to prevent further injury.',
  'page.safety.p1_s3': 'Call a medic or organiser.',
  'page.safety.p1_s4': 'Do not move the injured person unless necessary due to immediate danger.',
  'page.safety.p1_s5': 'In a serious case, call 155 or 112 and inform the organisers.',
  'page.safety.p2_title': 'When a child or participant is lost',
  'page.safety.p2_s1': 'Inform an organiser / registration / org tent immediately.',
  'page.safety.p2_s2': 'State the name, age, appearance, costume and where they were last seen.',
  'page.safety.p2_s3': 'Do not organise chaotic searching without arrangement with the organisers.',
  'page.safety.p2_s4': 'The organiser will determine the next steps.',
  'page.safety.p3_title': 'Fire',
  'page.safety.p3_s1': 'Warn those nearby.',
  'page.safety.p3_s2': 'Don’t fight the fire if it would endanger you.',
  'page.safety.p3_s3': 'Call an organiser.',
  'page.safety.p3_s4': 'Call 150 or 112 depending on the scale.',
  'page.safety.p3_s5': 'Clear access routes for the fire brigade.',
  'page.safety.p3_s6': 'Follow the organisers’ instructions.',
  'page.safety.p4_title': 'Storm, strong wind, extreme weather',
  'page.safety.p4_s1': 'Follow organiser instructions.',
  'page.safety.p4_s2': 'Don’t stay under solitary trees.',
  'page.safety.p4_s3': 'Secure tents and loose items.',
  'page.safety.p4_s4': 'When ordered to pause the game, end combat immediately and move to the designated place.',
  'page.safety.p5_title': 'Conflict / inappropriate behaviour / boundary violation',
  'page.safety.p5_s1': 'If it’s safe, clearly say that the behaviour bothers you.',
  'page.safety.p5_s2': 'If needed, contact an organiser, a confidant or a confidante.',
  'page.safety.p5_s3': 'Don’t resolve serious conflicts physically or with public lynching.',
  'page.safety.p5_s4': 'The organiser has the right to admonish, restrict or exclude a participant.',
