  'page.testimonials.title': 'Stimmen der Teilnehmer',
  'page.testimonials.meta_title': 'Stimmen der Teilnehmer — Schlacht um Mittelerde',
  'page.testimonials.description': 'Zitate, Erinnerungen und Erfahrungen aus früheren Jahrgängen der Schlacht um Mittelerde.',
  'page.testimonials.subtitle': 'Was diejenigen mitnehmen, die schon in Mittelerde waren.',
  'page.testimonials.alert_title': 'Wir sammeln weiter',
  'page.testimonials.alert_pre': 'Wir sammeln nach und nach Stimmen der Teilnehmer. Wenn du deinen Eindruck teilen willst, schreib uns an ',
  'page.testimonials.alert_post': '.',
  'page.testimonials.q1_text': 'Ich kam zum ersten Mal und war am zweiten Tag schon Teil der Truppe. Die Samstagsschlacht war das intensivste Erlebnis des Jahres.',
  'page.testimonials.q1_author': 'Tomáš · Gondor · 1. Mal',
  'page.testimonials.q2_text': 'Als meine Tochter sah, wie ihr die Elben am Abendfeuer eine Blumenkrone gaben, wusste ich, dass wir wiederkommen.',
  'page.testimonials.q2_author': 'Petr · Begleitung · Elternteil',
  'page.testimonials.q3_text': 'Der Freitag im Lager hatte eine Atmosphäre, die ich nicht beschreiben kann. Münzen, Wirtshaus, Verhandeln — genau das war es.',
  'page.testimonials.q3_author': 'Aneta · Rohan',
  'page.testimonials.cta_heading': 'Komm mit uns hin',
