  'page.a11y.title': 'Erklärung zur Barrierefreiheit',
  'page.a11y.description': 'Die Website der Schlacht um Mittelerde strebt die Konformität mit WCAG 2.1 AA an. Was wir getan haben, wo Grenzen liegen und wie du Probleme melden kannst.',
  'page.a11y.subtitle': 'Was wir getan haben, wo die Grenzen liegen, und wie du dich meldest, wenn etwas nicht funktioniert.',
  'page.a11y.toc_title': 'Seiteninhalt',
  'page.a11y.toc_aria': 'Inhalt der Erklärung zur Barrierefreiheit',
  'page.a11y.ch_compliance': 'Konformitätsstatus',
  'page.a11y.ch_limitations': 'Mögliche Einschränkungen',
  'page.a11y.ch_preparation': 'Erstellung der Erklärung',
  'page.a11y.ch_reporting': 'Meldung von Barrieren',
  'page.a11y.ch_enforcement': 'Durchsetzungsverfahren',
  'page.a11y.intro_p1_pre': 'Der Verein ',
  'page.a11y.intro_p1_strong': 'Moravian LARP, z. s.',
  'page.a11y.intro_p1_post': ' verpflichtet sich als Betreiber von www.panprstenu.cz dazu, die Barrierefreiheit seiner Websites in Übereinstimmung mit dem tschechischen Gesetz Nr. 99/2019 Slg. über die Barrierefreiheit von Websites und mobilen Anwendungen zu gewährleisten, das die Richtlinie (EU) 2016/2102 des Europäischen Parlaments und des Rates umsetzt.',
  'page.a11y.intro_p2': 'Diese Erklärung zur Barrierefreiheit gilt für www.panprstenu.cz und alle Unterseiten.',
  'page.a11y.compliance_p': 'Die Website strebt die Konformität mit WCAG 2.1 Stufe AA an und berücksichtigt die Empfehlungen von EN 301 549. Einige Inhalte können in bestimmten Kontexten kleinere Anpassungen erfordern — diese arbeiten wir laufend ab.',
  'page.a11y.compliance_h': 'Was wir getan haben',
  'page.a11y.compliance_l1': 'Skip-to-Content-Link zum Hauptinhalt (Tab von URL).',
  'page.a11y.compliance_l2': 'Semantische HTML-Struktur mit Landmarks (header, nav, main, footer).',
  'page.a11y.compliance_l3': 'Tastatur-Bedienbarkeit aller interaktiven Elemente (Tab, Shift+Tab, Enter, Space, Esc).',
  'page.a11y.compliance_l4': 'Sichtbarer Fokusring in markanter Goldfarbe.',
  'page.a11y.compliance_l5': 'Textkontrast ≥ 4.5:1 für normalen Text, ≥ 3:1 für großen Text.',
  'page.a11y.compliance_l6': 'Akkordeons für Regeln und Organisatorisches nutzen natives <details> — funktionieren ohne JavaScript und mit Screenreadern.',
  'page.a11y.compliance_l7_intro': 'Schwebendes Barrierefreiheits-Panel (unten rechts) — der Nutzer kann:',
  'page.a11y.compliance_l7_a': 'Schrift vergrößern (normal / größer / am größten),',
  'page.a11y.compliance_l7_b': 'hohen Kontrast aktivieren,',
  'page.a11y.compliance_l7_c': 'auf eine serifenlose Schrift wechseln (geeignet bei Legasthenie),',
  'page.a11y.compliance_l7_d': 'Animationen reduzieren,',
  'page.a11y.compliance_l7_e': 'Zeilenabstand erhöhen.',
  'page.a11y.compliance_l8': 'Respekt für Systempräferenzen prefers-reduced-motion und prefers-color-scheme.',
  'page.a11y.compliance_l9': 'Sinnvolle Bildtexte und alternative Beschreibungen, wo nötig.',
  'page.a11y.compliance_l10': 'Hreflang für 5 Sprachversionen (cs, en, de, sk, uk).',
  'page.a11y.compliance_l11': 'Druckversion der Seiten (probier Strg/Cmd+P).',
  'page.a11y.compliance_l12': 'Stilkonsistenz und Unterstützung von 100% Browser-Zoom (Strg/Cmd +).',
  'page.a11y.lim_p': 'Einige Teile der Website können in Einzelfällen kleinere Abweichungen von WCAG 2.1 AA aufweisen. Konkret:',
  'page.a11y.lim_l1_pre': 'Die eingebettete Google Maps im Abschnitt ',
  'page.a11y.lim_l1_link': 'Wie du zu uns kommst',
  'page.a11y.lim_l1_post': ' ist ein Drittanbieter; ihre Barrierefreiheit verwaltet Google. Den Veranstaltungsort geben wir auch separat als Klartext an (GPS-Koordinaten + Link).',
  'page.a11y.lim_l2': 'Dekorative Bilder (Eckornamente, Wachssiegel, Trennlinien) haben aria-hidden="true" — sie sind für Screenreader ausgeblendet, um das Hörerlebnis nicht zu überladen.',
  'page.a11y.lim_l3': 'Die Fotogalerie aus früheren Jahrgängen hat noch keine automatischen Alternativtexte für jede Aufnahme — wird bis zum MVP-Launch ergänzt.',
  'page.a11y.prep_p1': 'Diese Erklärung wurde am 30. April 2026 auf Grundlage einer Selbstbewertung erstellt, die direkt vom Betreiber durchgeführt wurde (Tests mit Tastatur, Screenreader, automatisierten Tools und manueller Kontrastprüfung).',
  'page.a11y.prep_p2': 'Die Erklärung wurde zuletzt am 30. April 2026 überprüft.',
  'page.a11y.report_h': 'Meldung von Barrieren und alternativer Inhalt',
  'page.a11y.report_p': 'Wenn du auf Inhalte oder Funktionen gestoßen bist, die mit Screenreader, Tastatur oder anderem Hilfsmittel nicht gut nutzbar sind, schreib uns. Wir versuchen, das zu beheben, und stellen den Inhalt zwischenzeitlich in einer anderen, zugänglichen Form bereit.',
  'page.a11y.contact_h': 'Kontakt',
  'page.a11y.contact_provider_label': 'Betreiber',
  'page.a11y.contact_email_label': 'E-Mail',
  'page.a11y.contact_subject_label': 'E-Mail-Betreff',
  'page.a11y.contact_subject_value': '„Barrierefreiheit der Website — …"',
  'page.a11y.contact_response': 'Wir antworten spätestens innerhalb von 30 Tagen gemäß § 9 des tschechischen Gesetzes Nr. 99/2019 Slg.',
  'page.a11y.enf_h': 'Durchsetzungsverfahren',
  'page.a11y.enf_p_pre': 'Wenn du uns kontaktiert hast und keine zufriedenstellende Antwort erhalten hast, kannst du Beschwerde bei der Aufsichtsbehörde einreichen, dem ',
  'page.a11y.enf_p_strong': 'Innenministerium der Tschechischen Republik',
  'page.a11y.enf_p_post': ':',
  'page.a11y.enf_address_label': 'Adresse',
  'page.a11y.enf_address_value': 'nám. Hrdinů 1634/3, 140 21 Prag 4, Tschechien',
  'page.a11y.enf_email_label': 'E-Mail',
