  'page.vendors.title': 'Stände und Verkäufer',
  'page.vendors.description': 'Thematische Stände und Verkäufer bei der Schlacht um Mittelerde 2026 — Kostüme, Stoffe, Lederzubehör, Schmuck, Waffen und weitere Mittelerde-Ausrüstung.',
  'page.vendors.subtitle': 'Markt, Handwerk und Dinge, die nach Mittelerde gehören.',
  'page.vendors.intro': 'Vor Ort findest du thematische Ausrüstung — Kostüme, Stoffe, Lederzubehör, Schmuck, Waffen und weitere Dinge, die in Mittelerde nützlich sein können.',
  'page.vendors.warning': 'Die Organisatoren garantieren nicht, dass alles von allen vor Ort verfügbar ist. Wenn du etwas Bestimmtes von einem bestimmten Verkäufer brauchst, vereinbare es lieber vorher.',
