  'page.media.desc_strong1': 'Der Herr der Ringe — Schlacht um Mittelerde',
  'page.media.desc_mid': ' ist eine große Fantasy-Larp-Schlacht inspiriert von der Welt J. R. R. Tolkiens. Kostümierte Teilnehmer stellen Armeen und Völker Mittelerdes dar und nehmen an einem Spiel über das ganze Wochenende teil — mit Schwerpunkt auf Atmosphäre, Sicherheit, Fairness und Community. Veranstalter ist der Verein ',
