  'page.media.contact_subject_value': '„Medien — Schlacht um Mittelerde"',
  'page.media.contact_response': 'Für Berichte vor Ort bitten wir um Akkreditierung mindestens 7 Tage vorher. Gib Medienart, geplantes Format und Personenzahl an.',
