  'page.safety.meta_title': 'Sicherheit und Krisensituationen',
  'page.safety.description': 'Praktischer Überblick, was bei Verletzung, vermisstem Kind, Brand, Sturm oder Konflikt auf der Veranstaltung zu tun ist. Druckbare Version fürs Lager.',
  'page.safety.bc_label': 'Sicherheit',
  'page.safety.title': 'Sicherheit und Krisensituationen',
  'page.safety.subtitle': 'Was tun, wenn etwas passiert. Kurze praktische Karte — ausdrucken, mitnehmen.',
  'page.safety.card_title': 'Schnelle Sicherheitskarte',
  'page.safety.emergency_label': 'Notruf',
