  'page.safety.gps_label': 'GPS',
  'page.safety.main_org_label': 'Hauptorganisator',
  'page.safety.main_org_name': 'Mealtiner',
  'page.safety.email_label': 'E-Mail',
  'page.safety.medic_label': 'Sanitäter vor Ort',
  'page.safety.medic_value': 'Bei der Registrierung / am Org-Zelt (qualifizierter Sanitäter während der gesamten Veranstaltung)',
  'page.safety.print_tip': 'Tipp: Drucke diese Karte aus (Strg/Cmd+P) und nimm sie mit. Das Signal in der Umgebung ist nicht immer zuverlässig.',
  'page.safety.h_procedures': 'Vorgehen in Krisensituationen',
  'page.safety.p1_title': 'Wenn sich jemand verletzt',
  'page.safety.p1_s1': 'Unterbrich die gefährliche Tätigkeit.',
  'page.safety.p1_s2': 'Sichere die Umgebung, um weitere Verletzungen zu verhindern.',
  'page.safety.p1_s3': 'Rufe den Sanitäter oder einen Organisator.',
  'page.safety.p1_s4': 'Bewege den Verletzten nicht, sofern es nicht wegen unmittelbarer Gefahr nötig ist.',
  'page.safety.p1_s5': 'Bei einem ernsten Zustand wähle 155 oder 112 und informiere die Organisatoren.',
  'page.safety.p2_title': 'Wenn ein Kind oder Teilnehmer verloren geht',
  'page.safety.p2_s1': 'Informiere sofort einen Organisator / die Registrierung / das Org-Zelt.',
  'page.safety.p2_s2': 'Nenne Name, Alter, Aussehen, Kostüm und wo die Person zuletzt gesehen wurde.',
  'page.safety.p2_s3': 'Veranstalte keine chaotische Suche ohne Absprache mit den Organisatoren.',
  'page.safety.p2_s4': 'Der Organisator legt das weitere Vorgehen fest.',
  'page.safety.p3_title': 'Brand',
  'page.safety.p3_s1': 'Warne die Umgebung.',
  'page.safety.p3_s2': 'Lösche nicht, wenn du dich dadurch gefährden würdest.',
  'page.safety.p3_s3': 'Rufe einen Organisator.',
  'page.safety.p3_s4': 'Wähle 150 oder 112 je nach Ausmaß.',
  'page.safety.p3_s5': 'Halte die Zufahrtswege für die Feuerwehr frei.',
  'page.safety.p3_s6': 'Befolge die Anweisungen der Organisatoren.',
  'page.safety.p4_title': 'Gewitter, starker Wind, extremes Wetter',
  'page.safety.p4_s1': 'Befolge die Anweisungen der Organisatoren.',
  'page.safety.p4_s2': 'Halte dich nicht unter einzelnen Bäumen auf.',
  'page.safety.p4_s3': 'Sichere Zelte und lose Gegenstände.',
  'page.safety.p4_s4': 'Bei der Anweisung zur Spielunterbrechung beende den Kampf sofort und gehe an den festgelegten Ort.',
  'page.safety.p5_title': 'Konflikt / unangemessenes Verhalten / Grenzverletzung',
  'page.safety.p5_s1': 'Wenn es sicher ist, sag deutlich, dass dich das Verhalten stört.',
  'page.safety.p5_s2': 'Wende dich bei Bedarf an einen Organisator, eine Vertrauensperson.',
  'page.safety.p5_s3': 'Löse ernste Konflikte nicht körperlich oder durch öffentliche Lynchjustiz.',
  'page.safety.p5_s4': 'Der Organisator hat das Recht, einen Teilnehmer zu ermahnen, einzuschränken oder auszuschließen.',
  'page.safety.p6_title': 'Alkohol und Rauschmittel',
  'page.safety.p6_s1': 'Unter Alkohol- oder Rauschmitteleinfluss ist die Schlacht nicht erlaubt.',
  'page.safety.p6_s2': 'Während der Schlacht ist der Konsum strikt verboten.',
  'page.safety.p6_s3': 'Der Organisator kann einen Teilnehmer von der Schlacht oder der Veranstaltung ausschließen.',
