  'page.organizer.intro': 'Володар Перснів — Битва за Середзем\'я — це багатоденний ларп-захід громадської організації Moravian LARP, z. s. Ця сторінка узагальнює повну ідентифікацію організатора для громадськості, партнерів, медіа, муніципальних органів та інших суб\'єктів.',
