  'page.a11y.title': 'Заява про доступність',
  'page.a11y.description': 'Сайт Битви за Середзем\'я прагне відповідати WCAG 2.1 AA. Що ми зробили, де є обмеження і як повідомити про проблему.',
  'page.a11y.subtitle': 'Що ми зробили, де межі та як зв\'язатися, коли щось не працює.',
