  'page.a11y.ch_limitations': 'Можливі обмеження',
  'page.a11y.ch_preparation': 'Підготовка заяви',
  'page.a11y.ch_reporting': 'Повідомлення про недоступність',
  'page.a11y.ch_enforcement': 'Процедура примусового виконання',
  'page.a11y.intro_p1_pre': 'Громадська організація ',
  'page.a11y.intro_p1_strong': 'Moravian LARP, z. s.',
  'page.a11y.intro_p1_post': ' як оператор сайту www.panprstenu.cz зобов\'язується забезпечити доступність своїх вебсторінок відповідно до чеського Закону № 99/2019 Зб. про доступність вебсайтів і мобільних застосунків, який імплементує Директиву (ЄС) 2016/2102 Європейського Парламенту та Ради.',
  'page.a11y.intro_p2': 'Ця заява про доступність стосується сайту www.panprstenu.cz і всіх його підсторінок.',
  'page.a11y.compliance_p': 'Сайт прагне відповідати WCAG 2.1 рівень AA і враховує рекомендації EN 301 549. Деякі частини контенту можуть у певних контекстах вимагати незначних коригувань — їх вирішуємо постійно.',
  'page.a11y.compliance_h': 'Що ми зробили',
  'page.a11y.compliance_l1': 'Посилання для пропуску до основного вмісту (Tab з URL).',
  'page.a11y.compliance_l2': 'Семантична HTML-структура з лендмарками (header, nav, main, footer).',
  'page.a11y.compliance_l3': 'Керування з клавіатури усіх інтерактивних елементів (Tab, Shift+Tab, Enter, Space, Esc).',
  'page.a11y.compliance_l4': 'Видимий focus ring у яскравому золотистому кольорі.',
  'page.a11y.compliance_l5': 'Контраст тексту ≥ 4.5:1 для звичайного тексту, ≥ 3:1 для великого тексту.',
  'page.a11y.compliance_l6': 'Акордеони правил і організації використовують нативний <details> — працюють без JavaScript і зі скрін-рідерами.',
  'page.a11y.compliance_l7_intro': 'Плаваюча панель доступності (праворуч знизу) — користувач може:',
  'page.a11y.compliance_l7_a': 'збільшити шрифт (нормальний / більший / найбільший),',
  'page.a11y.compliance_l7_b': 'увімкнути високий контраст,',
  'page.a11y.compliance_l7_c': 'перемкнути на безсерифний шрифт (підходить при дислексії),',
  'page.a11y.compliance_l7_d': 'обмежити анімації,',
  'page.a11y.compliance_l7_e': 'збільшити міжрядковий інтервал.',
  'page.a11y.compliance_l8': 'Повага до системних налаштувань prefers-reduced-motion і prefers-color-scheme.',
  'page.a11y.compliance_l9': 'Змістовні тексти зображень і альтернативні описи там, де це потрібно.',
  'page.a11y.compliance_l10': 'Hreflang для 5 мовних версій (cs, en, de, sk, uk).',
  'page.a11y.compliance_l11': 'Версія сторінок для друку (спробуй Ctrl/Cmd+P).',
  'page.a11y.compliance_l12': 'Стильова узгодженість і підтримка 100% масштабування у браузері (Ctrl/Cmd +).',
  'page.a11y.lim_p': 'Деякі частини сайту можуть в окремих випадках мати незначні відхилення від WCAG 2.1 AA. Зокрема:',
  'page.a11y.lim_l1_pre': 'Вбудована карта Google Maps у розділі ',
  'page.a11y.lim_l1_link': 'Як до нас дістатися',
  'page.a11y.lim_l1_post': ' — третя сторона, її доступністю керує Google. Місце заходу також наводимо окремо як простий текст (GPS-координати + посилання).',
  'page.a11y.lim_l2': 'Декоративні зображення (кутові орнаменти, воскові печатки, розділювачі) мають aria-hidden="true" — вони приховані від скрін-рідерів, щоб не перевантажувати прослуховування.',
  'page.a11y.lim_l3': 'Фотогалерея з минулих років поки не має автоматичних альтернативних описів для кожного кадру — буде доповнено до MVP-релізу.',
  'page.a11y.prep_p1': 'Цю заяву було підготовлено 30 квітня 2026 на основі самооцінки, проведеної безпосередньо оператором (тестовано клавіатурою, скрін-рідером, автоматизованими інструментами та ручною перевіркою контрасту).',
  'page.a11y.prep_p2': 'Заяву востаннє переглянуто 30 квітня 2026.',
