  'page.a11y.report_p': 'Якщо ви натрапили на контент чи функцію, яку важко використовувати зі скрін-рідером, клавіатурою або іншим допоміжним інструментом, напишіть нам. Спробуємо це виправити, а тим часом надамо контент в іншій, доступній формі.',
