  'page.attendees.title': 'Хто їде',
  'page.attendees.meta_title': 'Хто їде — Володар Перснів 2026',
  'page.attendees.description': 'Публічний огляд зареєстрованих учасників заходу Володар Перснів 2026. Подивися, хто вже збирається до Середзем\'я і як заповнюються сторони та армії.',
