  'page.org_team.tag': 'Команда заходу',
  'page.org_team.subtitle': 'Люди, які будують Середзем\'я.',
  'page.org_team.description': 'Команда, що готує Володаря Перснів 2026. Люди, які будують Середзем\'я — від сюжету через безпеку до дитячої гри і ярмарку.',
  'page.org_team.intro_p1': 'Ця сторінка представляє команду, що готує Володаря Перснів 2026 і веде увесь вікенд. Це не роль, на яку учасники реєструються — організаторська команда формується довгостроковою співпрацею у спільноті.',
