  'page.org_team.r6_title': 'Дитяча гра',
  'page.org_team.r6_desc': 'Програма для маленьких шукачів пригод, нагляд за безпекою та інфраструктура для батьків.',
  'page.org_team.r7_title': 'Стенди та ярмарок',
  'page.org_team.r7_desc': 'Домовленість зі стендистами, координація з корчмою U Zeleného draka, ярмаркова атмосфера.',
  'page.org_team.r8_title': 'Фото, відео та медіа',
  'page.org_team.r8_desc': 'Офіційний фотограф/оператор, медійна співпраця, галерея після заходу.',
  'page.org_team.alert_rotate': 'Командні ролі можуть у різні роки трохи відрізнятися. Деякі частини (напр. дитяча гра, медійна координація) ведуть ті самі люди постійно, інші ротуються залежно від доступності.',
  'page.org_team.h_contact': 'Як з нами зв\'язатися',
  'page.org_team.contact_intro': 'Загальні запитання надсилай на головну електронну пошту:',
  'page.org_team.contact_l1': 'Реєстрація, оплата, логістика',
  'page.org_team.contact_l2': 'Медіа і преса',
  'page.org_team.contact_l2_label': 'Для медіа',
  'page.org_team.contact_l3': 'Стендисти і бізнес-співпраця',
  'page.org_team.contact_l3_label': 'Для стендистів',
  'page.org_team.contact_l4': 'Безпека і кризові ситуації',
  'page.org_team.contact_l4_label': 'Безпека',
  'page.org_team.contact_note': 'Конкретні контакти окремих організаторів додамо поступово, щойно будуть готові публічні представлення.',
  'page.org_team.h_join': 'Хочеш долучитися?',
  'page.org_team.join_intro': 'Команда не закритий клуб. Людей, які хочуть довгостроково долучатися до підготовки, вітаємо. Зазвичай так:',
  'page.org_team.join_step1': 'Приїдь на захід як учасник — пізнай, як це працює зсередини.',
  'page.org_team.join_step2_pre': 'У наступному році запропонуй себе як ',
  'page.org_team.join_step2_link': 'помічника',
  'page.org_team.join_step2_post': ' у конкретній галузі.',
  'page.org_team.join_step3': 'Після заходу домовимось, чи і як має сенс продовжувати далі.',
