  'page.photographers.yes_l3': 'костюми і деталі спорядження,',
  'page.photographers.yes_l4': 'п’ятнична супровідна програма,',
  'page.photographers.yes_l5': 'атмосферу вечірнього табору,',
  'page.photographers.yes_l6': 'ятки, ремесла, корчму і спільноту,',
  'page.photographers.yes_l7': 'суботню головну гру з безпечної відстані,',
  'page.photographers.yes_l8': 'дитячу гру лише обережно і з повагою до батьків і правил організатора.',
  'page.photographers.h_what_no': 'Невідповідні кадри',
  'page.photographers.no_l1': 'поранення і втручання медиків,',
  'page.photographers.no_l2': 'делікатні особисті ситуації,',
  'page.photographers.no_l3': 'переодягання, гігієну, приватність наметів,',
  'page.photographers.no_l4': 'дітей без розумного контексту і згоди,',
  'page.photographers.no_l5': 'ситуації, які могли б когось присоромити або зашкодити йому.',
  'page.photographers.h_move': 'Пересування під час гри',
  'page.photographers.move_intro': 'Під час головної суботньої гри діє:',
  'page.photographers.move_l1': 'тримайся подалі від прямого бою,',
