  'page.stalls.h_what': 'Що пасує до заходу',
  'page.stalls.what_intro': 'Вітаємо насамперед речі, що вписуються в атмосферу фентезі, табору, ремесла і пригод. Підходящі типи яток:',
  'page.stalls.what_l1': 'шкіряні вироби,',
  'page.stalls.what_l2': 'прикраси, амулети, аксесуари,',
  'page.stalls.what_l3': 'фентезі- і ларп-спорядження,',
  'page.stalls.what_l4': 'костюмні аксесуари,',
  'page.stalls.what_l5': 'ручна робота,',
  'page.stalls.what_l6': 'ремісничі демонстрації та воркшопи,',
  'page.stalls.what_l7': 'дрібні тематичні ігри та активності,',
  'page.stalls.what_l8': 'послуги для учасників у таборі,',
  'page.stalls.what_l9': 'тематичний продаж, що вписується у світ Середзем’я.',
  'page.stalls.h_gastro': 'Гастрозаклади',
  'page.stalls.gastro_p1_pre': 'Гастрозаклади треба узгоджувати індивідуально наперед. На заході маємо виключну домовленість з корчмою ',
