  'page.kids.cos_l3': 'хустка,',
  'page.kids.cos_l4': 'жилетка,',
  'page.kids.cos_l5': 'пояс,',
  'page.kids.cos_l6': 'зручні штани,',
  'page.kids.cos_l7': 'міцне взуття,',
  'page.kids.cos_l8': 'природні кольори.',
  'page.kids.cos_note': 'Важливіше за ідеальний вигляд — комфорт, безпека і те, щоб дитина почувалася добре.',
  'page.kids.h_take': 'Що дітям взяти з собою',
